# shellcheck shell=bash
# Host side of the FreeRADIUS fixture `radius` (lane 1D-a), sourced by
# scripts/interop/run.sh. See the layout contract in scripts/interop/lib.sh.
#
# Container rskrb5-interop-radius (hostname and network alias
# radius.test.rskrb5 on rskrb5-interop): the RADIUS backend of the MIT KDC's
# OTP preauthentication. The KDC reaches it as radius.test.rskrb5:1812; UDP
# 1812 is published on 127.0.0.1:INTEROP_RADIUS_PORT (default 19001, lane 1D-a
# range 19000-19099). The per-run shared secret and OTP token are generated by
# the mit-kdc fixture (INTEROP_RADIUS_SHARED_SECRET, INTEROP_MIT_OTP_TOKEN),
# which therefore starts first. No extra capability and no --privileged.
#
# This fixture has no Rust suite of its own: the current crate cannot drive
# OTP; it is proven by the self-check below, which also runs the KDC side
# (scripts/interop/mit/preauth/selfcheck/40-otp.sh).

interop_fixture radius

# Prints the redacted log of the radius container (secrets of this run removed).
interop_radius_log() {
  local container name
  local -a secrets=()
  container="$(interop_container_name radius)"
  for name in "${INTEROP_ENV_NAMES[@]}"; do
    interop_is_secret_name "$name" && secrets+=("${!name:-}")
  done
  interop_rt logs "$container" 2>&1 | interop_redact_stream "${secrets[@]}"
}

# interop_radius_selfcheck: proves the RADIUS fixture and the KDC's OTP module.
#  1. radclient inside the radius container: the token is accepted, a wrong one
#     rejected (radiusd answers).
#  2. the MIT client tools in the mit-kdc container authenticate otpuser with
#     FAST + OTP through the KDC (40-otp.sh asserts the trace and the KDC log).
#  3. the RADIUS server's own log, read only after the radclient step, shows one
#     accepted and one rejected login for otpuser: the KDC consulted RADIUS
#     (mechanism proof for the OTP backend; the radclient requests are excluded).
interop_radius_selfcheck() {
  local container seen log
  container="$(interop_container_name radius)"
  interop_log "fixture radius: self-check radclient"
  interop_rt exec "$container" /opt/interop/radius/selfcheck.sh >&2 ||
    interop_die "fixture radius (container $container): radclient self-check failed" || return 1
  seen="$(interop_radius_log | wc -l)"
  interop_mit_run_selfcheck "$(interop_container_name mit-kdc)" 40-otp ||
    interop_die "fixture radius (container $container): the KDC OTP self-check failed" || return 1
  log="$(interop_radius_log | tail -n "+$((seen + 1))")"
  grep -Eq 'Login OK: \[otpuser\]' <<<"$log" ||
    interop_die "fixture radius (container $container): radiusd logged no accepted login for otpuser from the KDC" || return 1
  grep -Eq 'Login incorrect .*\[otpuser\]' <<<"$log" ||
    interop_die "fixture radius (container $container): radiusd logged no rejected login for otpuser from the KDC" || return 1
  interop_log "selfcheck[radius]: PASS radiusd logged the KDC's requests: $(grep -E 'Login (OK|incorrect).*\[otpuser\]' <<<"$log" | cut -c1-150 | tr '\n' '|')"
}

fixture_radius_up() {
  local fixture=radius container image dir port
  container="$(interop_container_name "$fixture")"
  local host=127.0.0.1
  port="${INTEROP_RADIUS_PORT:-19001}"
  dir="$INTEROP_ROOT/scripts/interop/radius"
  [[ -n "${INTEROP_RADIUS_SHARED_SECRET:-}" && -n "${INTEROP_MIT_OTP_TOKEN:-}" ]] ||
    interop_die "fixture $fixture needs the secrets of fixture mit-kdc: start mit-kdc first" || return 1

  image="$(interop_build_image radius "$dir")" || return 1
  interop_env INTEROP_RADIUS_IMAGE "$image"
  interop_run_container "$fixture" "$image" \
    --hostname radius.test.rskrb5 --network-alias radius.test.rskrb5 \
    -p "$host:$port:1812/udp" || interop_die "fixture $fixture: container $container did not start" || return 1
  interop_deliver_secrets "$container" INTEROP_RADIUS_SHARED_SECRET INTEROP_MIT_OTP_TOKEN || return 1
  interop_wait_ready "$fixture" || return 1

  interop_env INTEROP_RADIUS_CONTAINER "$container"
  interop_env INTEROP_RADIUS_HOST "$host"
  interop_env INTEROP_RADIUS_PORT "$port"
  interop_env INTEROP_RADIUS_ENDPOINT "$host:$port"
  interop_env INTEROP_RADIUS_USER otpuser
  interop_radius_selfcheck
}
